#include<bits/stdc++.h>using namespace std; int main(){    string s;    cin >> s;    string ans;    int n = s.size();    for(int i=0;i<n;i++)    {        s[i] = tolower((unsigned char)s[i]);        if(s[i] == 'y' || s[i] == 'a' || s[i] == 'e' || s[i] == 'i' || s[i] == 'o' || s[i] == 'u')        {            ans = ans + "";        }        else        {            ans = ans + "." + s[i];        }    }    cout << ans << endl;}